{
  "name": "oc-sidebar-extra",
  "version": "0.1.0",
  "type": "module",
  "private": true,
  "description": "Extra OpenCode v2 sidebar blocks: subagents, usage detail, tool activity",
  "keywords": ["opencode-plugin"],
  "license": "MIT",
  "exports": {
    "./server": "./src/server.ts",
    "./tui": "./src/tui.tsx"
  },
  "scripts": {
    "typecheck": "tsc --noEmit"
  },
  "peerDependencies": {
    "@opencode/plugin": ">=2.1.3",
    "@opentui/core": ">=0.6.6",
    "@opentui/solid": ">=0.6.6",
    "solid-js": ">=1.9.0"
  },
  "devDependencies": {
    "@opencode/client": "^2.1.3",
    "@opencode/plugin": "^2.1.3",
    "@opencode/theme": "^2.1.3",
    "@opentui/core": "^0.6.6",
    "@opentui/solid": "^0.6.6",
    "@types/node": "^26.6.5",
    "solid-js": "^1.9.0",
    "typescript": "^5.9.0"
  }
}

// Server half of oc-sidebar-extra.
//
// 2.1.3 refuses to load a plugin directory when `server` (and `index`) resolve
// to nothing, so this stub registers an id and does nothing else. tui.tsx holds
// the sidebar blocks.
import { Plugin } from "@opencode/plugin"

export default Plugin.define({
	id: "oc-sidebar-extra",
	setup() {},
})
